from pathlib import Path
ROOT = Path(__file__).resolve().parent
def p(d, **attrs):
    a=' '.join(f'{k.replace("_","-")}="{v}"' for k,v in attrs.items())
    return f'<path d="{d}" {a}/>'
def c(x,y,r,**attrs):
    a=' '.join(f'{k.replace("_","-")}="{v}"' for k,v in attrs.items())
    return f'<circle cx="{x}" cy="{y}" r="{r}" {a}/>'
def rect(x,y,w,h,rx=1):
    return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{rx}"/>'
